// Shared paths for the browser-test fixtures generated by ./server.ts.
//
// The server writes a real, freshly signed SD-JWT VC to this temporary file at
// startup; the Playwright tests read it to paste or upload it. Keeping it out
// of the repository avoids committing a credential-looking artifact while still
// exercising the real validation API.

import { tmpdir } from 'node:os'
import { join } from 'node:path'

export const PID_CREDENTIAL_FIXTURE = join(tmpdir(), 'attestbook-e2e-pid-credential.txt')
